#!/usr/bin/env python3
"""Build standalone, table-based acceptance emails. No sending or recipient logic."""
import json, pathlib, html
R=pathlib.Path(__file__).resolve().parents[1]
BASE='https://ilyyeees.github.io/gdg-emails-regs'
D=[
('Events','events','I','The gathering begins.','Architects of the gathering','Bring people together. Turn an idea into a moment that matters.','#e5bd77','AMBER / ASSEMBLY','An illuminated lantern, celestial chart, and parchment scroll'),
('Multimedia','multimedia','II','Make the moment live.','Keepers of the story','Capture the energy. Give every moment a story worth sharing.','#ef9a99','CRIMSON / MEMORY','An enchanted camera and cinematic relics'),
('Production','production','III','Bring the vision to life.','Makers behind the magic','Shape the details. Turn ambitious ideas into work people can experience.','#dda77f','COPPER / CREATION','A quill, ornate gears, and crafted production instruments'),
('Mobile Development','mobile-development','IV','Build beyond the page.','Makers of pocket worlds','Build thoughtful mobile experiences, one interaction at a time.','#8ed6ad','EMERALD / MOTION','An emerald phone grimoire and arcane engineering instruments'),
('Web Development','web-development','V','Open a new world.','Architects of the connected','Turn ideas into interfaces. Build places where people and possibilities meet.','#99cce9','AZURE / CONNECTION','A luminous portal and connected web architecture'),
('Relex','relex','VI','Forge meaningful bonds.','Envoys of possibility','Start conversations. Build the connections that help a community grow.','#a6bdf0','SAPPHIRE / ALLIANCE','An ornate diplomatic relic and celestial instruments'),
('UI/UX','ui-ux','VII','Give possibility a form.','Readers of the human side','Listen closely. Shape experiences that feel clear, useful, and human.','#c9b0ef','AMETHYST / INTENTION','Amethyst interface panels, a drafting compass, and a cursor'),
('Robotics','robotics','VIII','Set ideas in motion.','Builders of living machines','Bring code into the physical world. Make curiosity move.','#8bd7cc','TEAL / INVENTION','A mechanical automaton hand and brass engineering relics'),
('AI','ai','IX','Explore the unknown.','Seekers of new intelligence','Ask better questions. Explore what intelligent systems can make possible.','#d1b5f5','VIOLET / DISCOVERY','A violet and gold neural astrolabe'),
('Graphic Design','graphic-design','X','Make your mark.','Authors of the visual','Give ideas a visual voice. Create work that makes people stop and look.','#e8a6cc','ROSE / EXPRESSION','A magical designer’s grimoire and drawing instruments')]
(R/'emails').mkdir(exist_ok=True)
for name,slug,n,title,role,mission,accent,code,alt in D:
 image=f'{BASE}/assets/{slug}.png'
